import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;  // fake repository

    @InjectMocks
    private OrderService orderService;  // real service under test

    @Test
    void shouldCalculateTotalPrice() {
        var order = new Order(1L, "Laptop", 1200.0);
        when(orderRepository.findById(1L)).thenReturn(Optional.of(order));  // stub return value

        var total = orderService.calculateTotalWithTax(1L);

        assertEquals(1320.0, total);  // 1200 + 10% tax
        verify(orderRepository).findById(1L);  // assert the repo was called
    }
}
```

